import os,re,numpy as np,collections, re as re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G = load()

# Rule hypothesis under active testing:
# There is a "scatterer" cell of color s (distinct from background and dominant object color).
# The dominant objects (blobs) emit rays colored by s. Ray direction depends on pair orientation;
# ray passes through the object at the edge farthest in the direction, extending until it hits an
# obstruction or the grid edge. When a ray reaches the scatterer cell, that cell becomes 4.
# Obstructions encountered (other markers) are recolored to 4 instead.
# Ambiguity remaining for D2: which rows get beams when several scattered markers exist.

def find_doms_and_markers(a):
    h,w,a=np.shape(a); cnt=collections.Counter(v for row in a for v in row); bg=cnt.most_common(1)[0][0]
    nc={v:c for v,c in sorted(cnt.items()) if v!=bg}
    # blobs: connected components excluding bg
    blobs=[]; seen=set(); dirs=((1,0),(-1,0),(0,1),(0,-1))
    for r in range(h):
        for c in range(w):
            if a[r][c]!=bg and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); blob=[]
                while q:
                    cr,cc=q.pop(); blob.append((cr,cc))
                    for dr,dcs in dirs:
                        nr,nc_=cr+dr,cc+dcs
                        if 0<=nr<h and 0<=nc<w and (nr,nc_) not in seen and a[nr][nc_]==a[cr][cc]:
                            seen.add((nr,nc_)); q.append((nr,nc_))
                blobs.append(sorted(blob))
    return bg, nc, blobs, a, h, w

def beam(i, di, j):
    """ray starting at i in direction (di,dj): cells before including stop-where-obstruction"""
    rs=[]; rr,i,j=i,di,j
    while 0<=rr<i.shape[0] and 0<=jj<i.shape[1] and a[rr][jj]==8:
        rs.append((rr,jj)); rr+=di; jj+=dj
    return rs

