    i=np.array(G[demo]); o=np.array(G[demo.replace(' input',' output')])
    bg, nc, blobs, _, H,W = find_doms_and_markers(i)
    diffs=[((r,c), str(i[r,c]), str(o[r,c])) for r in range(H) for c in range(W) if i[r,c]!=o[r,c]]
    print('diffs:', diffs)

